class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);enableEdgeToEdge();setContent{STEMTrainingTheme{AppRoot()}}}}
@Composable private fun AppRoot(){val dao=remember{TrainingDatabase.getInstance(LocalContext.current).trainingDao()};val scope=rememberCoroutineScope();var page by remember{mutableStateOf("today")};when(page){"history"->HistoryScreen{page="today"};"stats"->StatisticsScreen{page="today"};"programs"->ProgramsScreen(onBack={page="today"}){p->scope.launch{val id=dao.insertWorkout(WorkoutEntity());p.exercises.forEach{dao.insertExercise(ExerciseEntity(workoutId=id,name=it))}};page="today"};else->TrainingScreen({page="history"},{page="stats"},{page="programs"})}}
data class CatalogExercise(val name:String,val muscle:String)
private val exerciseCatalog=listOf(CatalogExercise("Жим лёжа · штанга","Грудь"),CatalogExercise("Жим на наклонной скамье · штанга","Грудь"),CatalogExercise("Жим лёжа · гантели","Грудь"),CatalogExercise("Разведение рук лёжа · гантели","Грудь"),CatalogExercise("Отжимания","Грудь"),CatalogExercise("Тяга в наклоне · штанга","Спина"),CatalogExercise("Тяга в наклоне одной рукой · гантель","Спина"),CatalogExercise("Тяга верхнего блока","Спина"),CatalogExercise("Тяга горизонтального блока","Спина"),CatalogExercise("Подтягивания","Спина"),CatalogExercise("Приседания · штанга","Ноги"),CatalogExercise("Выпады · гантели","Ноги"),CatalogExercise("Жим ногами","Ноги"),CatalogExercise("Сгибание ног","Ноги"),CatalogExercise("Разгибание ног","Ноги"),CatalogExercise("Подъём на носки стоя","Икры"),CatalogExercise("Жим сидя · штанга","Плечи"),CatalogExercise("Жим сидя · гантели","Плечи"),CatalogExercise("Разведение рук в стороны · гантели","Плечи"),CatalogExercise("Разведение рук в наклоне · гантели","Плечи"),CatalogExercise("Шраги · гантели","Трапеции"),CatalogExercise("Сгибание рук · штанга","Бицепс"),CatalogExercise("Сгибание рук · гантели","Бицепс"),CatalogExercise("Молотковые сгибания · гантели","Бицепс"),CatalogExercise("Жим лёжа узким хватом · штанга","Трицепс"),CatalogExercise("Разгибание рук на блоке","Трицепс"),CatalogExercise("Французский жим · гантель","Трицепс"),CatalogExercise("Скручивания","Пресс"),CatalogExercise("Подъём ног","Пресс"),CatalogExercise("Планка","Пресс"))
@Composable fun TrainingScreen(history:()->Unit,stats:()->Unit,programs:()->Unit){val dao=remember{TrainingDatabase.getInstance(LocalContext.current).trainingDao()};val active by dao.observeActiveWorkout().collectAsState(initial=null);val completed by dao.observeCompletedWorkouts().collectAsState(initial=emptyList());val scope=rememberCoroutineScope();val wid=active?.id?:-1;val exercises by remember(wid){dao.observeExercises(wid)}.collectAsState(initial=emptyList());val sets by remember(wid){dao.observeSets(wid)}.collectAsState(initial=emptyList());var catalog by remember{mutableStateOf(false)};var addFor by remember{mutableStateOf<ExerciseEntity?>(null)};var edit by remember{mutableStateOf<WorkoutSetEntity?>(null)};var finish by remember{mutableStateOf(false)};val volume=sets.sumOf{it.weight*it.reps};Scaffold{pad->LazyColumn(Modifier.fillMaxSize().padding(pad).padding(horizontal=16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Spacer(Modifier.height(8.dp));Text("S.T.E.M. TRAINING",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold);Text(if(active==null)"Сегодня" else "Тренировка идёт",style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold);Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.End){TextButton(programs){Text("Программы")};TextButton(history){Text("История${if(completed.isEmpty())"" else " ${completed.size}"}")};TextButton(stats){Text("Статистика")}}};if(active==null)item{Card(Modifier.fillMaxWidth(),colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.surfaceVariant)){Column(Modifier.padding(20.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){Text("Нет активной тренировки",fontWeight=FontWeight.Bold);Text("Начни пустую тренировку или выбери готовую программу.");Button({scope.launch{dao.insertWorkout(WorkoutEntity())}},Modifier.fillMaxWidth()){Text("Начать пустую тренировку")};OutlinedButton(programs,Modifier.fillMaxWidth()){Text("Выбрать программу")}}}}else{item{WorkoutSummary(exercises.size,sets.size,volume)};items(exercises,key={it.id}){e->ExerciseCard(e,sets.filter{it.exerciseId==e.id},{addFor=e},{edit=it})};item{Button({catalog=true},Modifier.fillMaxWidth()){Text("+ Добавить упражнение")};TextButton({finish=true},Modifier.fillMaxWidth()){Text("Завершить тренировку")}}}};if(catalog&&active!=null)ExerciseCatalogDialog(exercises.map{it.name}.toSet(),{catalog=false}){n->scope.launch{dao.insertExercise(ExerciseEntity(workoutId=active!!.id,name=n))};catalog=false};addFor?.let{e->AddSetDialog(e.name,sets.lastOrNull{it.exerciseId==e.id},{addFor=null}){w,r->scope.launch{dao.insertSet(WorkoutSetEntity(exerciseId=e.id,weight=w,reps=r))};addFor=null}};edit?.let{s->EditSetDialog(s,{edit=null},{w,r->scope.launch{dao.updateSet(s.copy(weight=w,reps=r))};edit=null},{scope.launch{dao.deleteSet(s.id)};edit=null})};if(finish&&active!=null)AlertDialog(onDismissRequest={finish=false},title={Text("Завершить тренировку?")},text={Text("${exercises.size} упражнений · ${sets.size} подходов · ${formatNumber(volume)} кг")},confirmButton={TextButton({scope.launch{dao.finishWorkout(active!!.id)};finish=false}){Text("Завершить")}},dismissButton={TextButton({finish=false}){Text("Отмена")}})}
@Composable private fun ExerciseCard(e:ExerciseEntity,s:List<WorkoutSetEntity>,add:()->Unit,edit:(WorkoutSetEntity)->Unit){Card(Modifier.fillMaxWidth()){Column(Modifier.padding(18.dp)){Row{Text(e.name,Modifier.weight(1f),fontWeight=FontWeight.Bold);Text("＋",Modifier.clickable{add()}.padding(8.dp))};if(s.isEmpty())Text("Подходов пока нет")else s.forEachIndexed{i,x->Row(Modifier.fillMaxWidth().clickable{edit(x)}.padding(vertical=7.dp),horizontalArrangement=Arrangement.SpaceBetween){Text("${i+1} подход");Text("${formatNumber(x.weight)} кг × ${x.reps}",fontWeight=FontWeight.Bold)}}}}}
@Composable private fun EditSetDialog(s:WorkoutSetEntity,d:()->Unit,save:(Double,Int)->Unit,del:()->Unit){var w by remember(s){mutableStateOf(formatNumber(s.weight))};var r by remember(s){mutableStateOf(s.reps.toString())};AlertDialog(onDismissRequest=d,title={Text("Редактировать подход")},text={Column{OutlinedTextField(w,{w=it},label={Text("Вес")});OutlinedTextField(r,{r=it.filter(Char::isDigit)},label={Text("Повторения")});TextButton(del){Text("Удалить")}}},confirmButton={TextButton(onClick={w.replace(',','.').toDoubleOrNull()?.let{ww->r.toIntOrNull()?.let{rr->save(ww,rr)}}}){Text("Сохранить")}},dismissButton={TextButton(d){Text("Отмена")}})}
@Composable private fun ExerciseCatalogDialog(existing:Set<String>,d:()->Unit,select:(String)->Unit){var q by remember{mutableStateOf("")};val f=exerciseCatalog.filter{(it.name.contains(q,true)||it.muscle.contains(q,true))&&it.name !in existing};Dialog(onDismissRequest=d){Card{Column(Modifier.padding(18.dp)){Text("Каталог упражнений",fontWeight=FontWeight.Bold);OutlinedTextField(q,{q=it},label={Text("Поиск")});LazyColumn(Modifier.height(400.dp)){items(f){e->Row(Modifier.fillMaxWidth().clickable{select(e.name)}.padding(10.dp),horizontalArrangement=Arrangement.SpaceBetween){Text(e.name,Modifier.weight(1f));Text(e.muscle)}}};TextButton(d){Text("Закрыть")}}}}}
@Composable private fun AddSetDialog(n:String,p:WorkoutSetEntity?,d:()->Unit,add:(Double,Int)->Unit){var w by remember(p){mutableStateOf(p?.let{formatNumber(it.weight)}?:"")};var r by remember(p){mutableStateOf(p?.reps?.toString()?:"")};AlertDialog(onDismissRequest=d,title={Text("Новый подход")},text={Column{Text(n);OutlinedTextField(w,{w=it},label={Text("Вес")},keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Decimal));OutlinedTextField(r,{r=it.filter(Char::isDigit)},label={Text("Повторения")})}},confirmButton={TextButton(onClick={w.replace(',','.').toDoubleOrNull()?.let{ww->r.toIntOrNull()?.let{rr->add(ww,rr)}}}){Text("Добавить")}},dismissButton={TextButton(d){Text("Отмена")}})}
@Composable private fun WorkoutSummary(e:Int,s:Int,v:Double){Card(Modifier.fillMaxWidth()){Row(Modifier.fillMaxWidth().padding(18.dp),horizontalArrangement=Arrangement.SpaceBetween){SummaryValue(e.toString(),"упр.");SummaryValue(s.toString(),"подх.");SummaryValue(formatNumber(v),"кг");SummaryValue("идёт","статус")}}};@Composable private fun SummaryValue(v:String,l:String){Column(horizontalAlignment=Alignment.CenterHorizontally){Text(v,fontWeight=FontWeight.Bold);Text(l,style=MaterialTheme.typography.labelSmall)}};private fun formatNumber(v:Double)=if(v%1.0==0.0)v.toLong().toString() else v.toString()
